begin;
create extension if not exists pgtap with schema extensions;
select plan(8);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('00000000-0000-0000-0000-000000005001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','machine-feed@example.invalid','','{}','{}',now(),now());
insert into public.resource_registry(id,display_name,lifecycle_state,editorial_status) values ('00000000-0000-0000-0000-000000005101','Evidence Clinic','active','approved'),('00000000-0000-0000-0000-000000005102','Protected Transition House','active','approved');
insert into public.resource_fact_claims(id,resource_id,field_name,proposed_value,risk,recommendation,confidence,engine_version,status,claim_fingerprint) values ('00000000-0000-0000-0000-000000005201','00000000-0000-0000-0000-000000005101','location_occupancy','"100 Main Street, Surrey, BC"','medium','auto_accept','high','test','observed',repeat('a',64)),('00000000-0000-0000-0000-000000005202','00000000-0000-0000-0000-000000005102','location_occupancy','"200 Secret Road"','medium','auto_accept','high','test','observed',repeat('b',64));
insert into public.resource_fact_evidence(id,claim_id,source_type,source_url,source_authority,extraction_method,independent_key,evidence_fingerprint,extracted_value) values ('00000000-0000-0000-0000-000000005301','00000000-0000-0000-0000-000000005201','official_provider','https://example.invalid/clinic',95,'test','clinic',repeat('c',64),'{}'),('00000000-0000-0000-0000-000000005302','00000000-0000-0000-0000-000000005201','bc_geocoder','https://example.invalid/geocoder',95,'test','geocoder',repeat('d',64),'{"standardized_address":"100 Main Street, Surrey, BC","locality":"Surrey","municipality_match":true,"score":100,"precision_points":100,"location_descriptor":"parcelpoint","coordinates":{"latitude":49.1,"longitude":-122.8}}'),('00000000-0000-0000-0000-000000005303','00000000-0000-0000-0000-000000005202','official_provider','https://example.invalid/protected',95,'test','protected',repeat('e',64),'{}');
select ok(not has_function_privilege('anon','public.create_machine_initial_location_qc_from_evidence(uuid,uuid,uuid,uuid)','execute'),'anonymous denied');
select is((public.create_machine_initial_location_qc_from_evidence('00000000-0000-0000-0000-000000005101','00000000-0000-0000-0000-000000005201','00000000-0000-0000-0000-000000005302','00000000-0000-0000-0000-000000005001')).origin,'machine_initial','server-derived machine QC created');
select is((select review_snapshot->>'program_occupancy_confidence' from public.location_qc_reviews where canonical_resource_id='00000000-0000-0000-0000-000000005101'),'supported','occupancy derives from evidence');
select is((select review_snapshot->>'location_descriptor' from public.location_qc_reviews where canonical_resource_id='00000000-0000-0000-0000-000000005101'),'parcelpoint','geocoder derives from stored evidence');
select throws_ok($$select public.create_machine_initial_location_qc_from_evidence('00000000-0000-0000-0000-000000005101','00000000-0000-0000-0000-000000005201','00000000-0000-0000-0000-000000005302','00000000-0000-0000-0000-000000005001')$$,'PT409','current QC already exists; machine initial QC will not overwrite it','rerun preserves current QC');
select is((public.create_machine_initial_location_qc_from_evidence('00000000-0000-0000-0000-000000005102','00000000-0000-0000-0000-000000005202',null,'00000000-0000-0000-0000-000000005001')).review_snapshot->>'submitted_address',null,'protected address is withheld');
select is((select count(*)::integer from public.resource_locations),0,'machine feed creates no location');
select is((select count(*)::integer from public.resource_locations where public_map),0,'machine feed never publishes');
select * from finish(); rollback;
